use vstd::prelude::*;

verus! {

fn swap(arr: &Vec<i32>, i: usize, j: usize) -> (result: Vec<i32>)
    requires
        i < arr.len(),
        j < arr.len(),
    ensures
        result.len() == arr.len(),
        // swapped positions
        result[i as int] == arr[j as int],
        result[j as int] == arr[i as int],
        // all other positions unchanged
        forall|k: int|
            0 <= k < arr.len() && k != i as int && k != j as int
                ==> result[k] == arr[k],
{
    let n = arr.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut k: usize = 0;
    while k < n
        invariant
            result.len() == k,
            k <= n,
            n == arr.len(),
            i < n,
            j < n,
            forall|t: int|
                0 <= t < k as int ==> (
                    if t == i as int {
                        result[t] == arr[j as int]
                    } else if t == j as int {
                        result[t] == arr[i as int]
                    } else {
                        result[t] == arr[t]
                    }
                ),
        decreases n - k,
    {
        let val = if k == i {
            arr[j]
        } else if k == j {
            arr[i]
        } else {
            arr[k]
        };
        result.push(val);
        k = k + 1;
    }

    result
}

} // verus!

